from datetime import datetime
from typing import List, Optional, Literal, Dict, Any
from pydantic import BaseModel, Field, ConfigDict


class GeneratedFile(BaseModel):
    """An individual source code file generated by a developer agent."""

    file_path: str = Field(
        description="Relative file path within project root, e.g. backend/app/models/student.py"
    )
    content: str = Field(description="Full runnable source code content")
    description: str = Field(description="Brief description of what this file implements")
    file_type: Literal[
        "python", "typescript", "javascript", "json", "markdown", "sql", "yaml", "dockerfile", "other"
    ] = Field(default="python", description="File syntax type")


class TaskCodeOutput(BaseModel):
    """Structured code generation payload returned by developer agents."""

    task_key: str = Field(description="Associated task key, e.g. T1, T2")
    summary: str = Field(description="Executive summary of files created")
    files: List[GeneratedFile] = Field(
        description="List of concrete source files generated for this task"
    )
    instructions_for_next_agent: Optional[str] = Field(
        default=None, description="Export notes or contract caveats for downstream agents"
    )


class FileArtifactResponse(BaseModel):
    """Metadata response for a tracked file artifact."""

    id: str
    project_id: str
    task_id: Optional[str] = None
    file_path: str
    file_hash: str
    version: int
    generated_by_agent: str
    created_at: datetime
    updated_at: datetime

    model_config = ConfigDict(from_attributes=True)


class GenerationManifest(BaseModel):
    """Manifest summarizing all generated source files in the project workspace."""

    project_id: str
    project_name: str
    workspace_directory: str
    total_files: int
    files: List[Dict[str, Any]]
    generated_at: datetime

    model_config = ConfigDict(from_attributes=True)
